DELETE FROM subcategory_baseline
WHERE baseline_month = #{baselineMonth}

    AND marketplace = #{marketplace}

mapper.insert:
INSERT INTO subcategory_baseline ( marketplace, bsr_id, canonical_key, sub_category, baseline_month, sample_size, units_p50, units_p75, units_p90, price_p50, confidence, computed_at ) WITH filtered AS ( -- 数据清洗层：直接消费 competitor_products_clean（已按父 ASIN 去重） -- 见 docs/选品方法库/补充/数据清洗层.md SELECT cp.marketplace, cp.bsr_id, TRIM(SUBSTRING_INDEX(cp.node_label_path, ':', -1)) AS sub_category, cp.units, cp.price FROM competitor_products_clean cp WHERE cp.month = #{baselineMonth} AND cp.bsr_id IS NOT NULL AND cp.bsr_id != '' AND cp.node_label_path IS NOT NULL AND TRIM(SUBSTRING_INDEX(cp.node_label_path, ':', -1)) != '' AND LOWER(TRIM(SUBSTRING_INDEX(cp.node_label_path, ':', -1))) != 'null' AND cp.units IS NOT NULL
AND cp.marketplace = #{marketplace}
), units_ranked AS ( SELECT marketplace, bsr_id, sub_category, units, PERCENT_RANK() OVER ( PARTITION BY marketplace, bsr_id, sub_category ORDER BY units ) AS units_pr FROM filtered ), price_ranked AS ( SELECT marketplace, bsr_id, sub_category, price, PERCENT_RANK() OVER ( PARTITION BY marketplace, bsr_id, sub_category ORDER BY price ) AS price_pr FROM filtered WHERE price IS NOT NULL ), units_agg AS ( SELECT marketplace, bsr_id, sub_category, COUNT(*) AS sample_size, MAX(CASE WHEN units_pr <= 0.50 THEN units END) AS units_p50, MAX(CASE WHEN units_pr <= 0.75 THEN units END) AS units_p75, MAX(CASE WHEN units_pr <= 0.90 THEN units END) AS units_p90 FROM units_ranked GROUP BY marketplace, bsr_id, sub_category HAVING COUNT(*) >= 30 ), price_agg AS ( SELECT marketplace, bsr_id, sub_category, MAX(CASE WHEN price_pr <= 0.50 THEN price END) AS price_p50 FROM price_ranked GROUP BY marketplace, bsr_id, sub_category ) SELECT ua.marketplace, ua.bsr_id, NULL AS canonical_key, ua.sub_category, #{baselineMonth} AS baseline_month, ua.sample_size, ua.units_p50, ua.units_p75, ua.units_p90, pa.price_p50, CASE WHEN ua.sample_size >= 100 THEN 'high' WHEN ua.sample_size >= 30 THEN 'mid' ELSE 'low' END AS confidence, NOW() AS computed_at FROM units_agg ua LEFT JOIN price_agg pa ON pa.marketplace COLLATE utf8mb4_unicode_ci = ua.marketplace COLLATE utf8mb4_unicode_ci AND pa.bsr_id COLLATE utf8mb4_unicode_ci = ua.bsr_id COLLATE utf8mb4_unicode_ci AND pa.sub_category COLLATE utf8mb4_unicode_ci = ua.sub_category COLLATE utf8mb4_unicode_ci
